<?php defined('BASEPATH') OR exit('No direct script access allowed');
class Conversation_ops_model extends CI_Model {
 public function __construct(){parent::__construct();$this->load->database();$this->load->model('Conversation_model','conversations');}
 private function access($cid,$uid,$org){return $this->conversations->get($cid,$uid,$org);}
 public function participants($cid,$uid,$org){$conv=$this->access($cid,$uid,$org);if(!$conv)return NULL;$rows=$this->db->select('p.*,u.email,u.display_name')->from('conversation_participants p')->join('users u','u.id=p.user_id','left')->where('p.conversation_id',$cid)->order_by('p.joined_at')->get()->result_array();return array_map(function($r)use($conv){return array('id'=>$r['id'],'conversationId'=>$r['conversation_id'],'type'=>$r['user_id']?'user':'agent','userId'=>$r['user_id'],'agentId'=>$r['agent_id'],'name'=>$r['display_name']?:$r['email'],'email'=>$r['email'],'isCreator'=>$r['user_id']===$conv['createdById'],'joinedAt'=>$r['joined_at'],'lastReadAt'=>$r['last_read_at']);},$rows);}
 public function add($cid,$uid,$org,$d){$conv=$this->access($cid,$uid,$org);if(!$conv)return array(NULL,'conversation');$target=$d['userId']??NULL;$agent=$d['agentId']??NULL;if((bool)$target===(bool)$agent)return array(NULL,'choice');if($target){if(!$this->db->where(array('user_id'=>$target,'organization_id'=>$org))->count_all_results('memberships'))return array(NULL,'member');if($this->db->where(array('conversation_id'=>$cid,'user_id'=>$target))->count_all_results('conversation_participants'))return array(NULL,'duplicate');}else{if(!$this->db->where(array('id'=>$agent,'organization_id'=>$org))->count_all_results('agents'))return array(NULL,'agent');if($this->db->where(array('conversation_id'=>$cid,'agent_id'=>$agent))->count_all_results('conversation_participants'))return array(NULL,'duplicate');}$r=array('id'=>$this->uuid(),'conversation_id'=>$cid,'user_id'=>$target,'agent_id'=>$agent,'joined_at'=>date('Y-m-d H:i:s'),'last_read_at'=>NULL);$this->db->insert('conversation_participants',$r);$all=$this->participants($cid,$uid,$org);foreach($all as $v)if($v['id']===$r['id'])return array($v,NULL);}
 public function remove($cid,$pid,$uid,$org){$conv=$this->access($cid,$uid,$org);if(!$conv)return 'conversation';$r=$this->db->where(array('id'=>$pid,'conversation_id'=>$cid))->get('conversation_participants')->row_array();if(!$r)return 'missing';if($r['user_id']===$conv['createdById'])return 'creator';$this->db->where('id',$pid)->delete('conversation_participants');return NULL;}
 public function read_state($cid,$uid,$org,$mark=NULL){if(!$this->access($cid,$uid,$org))return NULL;$p=$this->db->where(array('conversation_id'=>$cid,'user_id'=>$uid))->get('conversation_participants')->row_array();if($mark!==NULL){if($p)$this->db->where('id',$p['id'])->update('conversation_participants',array('last_read_at'=>$mark));else{$this->db->insert('conversation_participants',array('id'=>$this->uuid(),'conversation_id'=>$cid,'user_id'=>$uid,'joined_at'=>date('Y-m-d H:i:s'),'last_read_at'=>$mark));}$last=$mark;}else $last=$p['last_read_at']??NULL;$this->db->from('messages')->where('conversation_id',$cid)->group_start()->where('user_id IS NULL',NULL,FALSE)->or_where('user_id !=',$uid)->group_end();if($last)$this->db->where('created_at >',$last);$unread=$this->db->count_all_results();$latest=$this->db->select('created_at')->where('conversation_id',$cid)->order_by('created_at','DESC')->limit(1)->get('messages')->row_array();return array('conversationId'=>$cid,'userId'=>$uid,'lastReadAt'=>$last,'basis'=>$last?'last_read_at':'never_marked_read','unreadCount'=>$unread,'excludesOwnMessages'=>TRUE,'latestMessageAt'=>$latest['created_at']??NULL);}
 public function stats($cid,$uid,$org){if(!$this->access($cid,$uid,$org))return NULL;$rows=$this->db->select('role,COUNT(*) count,COALESCE(SUM(tokens_in),0) tin,COALESCE(SUM(tokens_out),0) tout,COALESCE(SUM(cost_micros),0) cost,COALESCE(AVG(duration_ms),0) duration')->where('conversation_id',$cid)->group_by('role')->get('messages')->result_array();$by=array();$total=$ti=$to=$cost=0;$weighted=0;$timed=0;foreach($rows as $r){$role=strtolower($r['role']);$by[$role]=(int)$r['count'];$total+=(int)$r['count'];$ti+=(int)$r['tin'];$to+=(int)$r['tout'];$cost+=(int)$r['cost'];if($r['duration']>0){$weighted+=(float)$r['duration']*(int)$r['count'];$timed+=(int)$r['count'];}}$first=$this->db->select_min('created_at','v')->where('conversation_id',$cid)->get('messages')->row_array();$last=$this->db->select_max('created_at','v')->where('conversation_id',$cid)->get('messages')->row_array();return array('conversationId'=>$cid,'messageCount'=>$total,'messagesByRole'=>$by,'tokensIn'=>$ti,'tokensOut'=>$to,'totalTokens'=>$ti+$to,'costMicros'=>$cost,'averageDurationMs'=>$timed?(int)round($weighted/$timed):NULL,'firstMessageAt'=>$first['v'],'lastMessageAt'=>$last['v'],'measured'=>TRUE);}
 public function transcript($cid,$uid,$org,$includeSystem=TRUE){$conv=$this->access($cid,$uid,$org);if(!$conv)return NULL;$this->db->where('conversation_id',$cid);if(!$includeSystem)$this->db->where('role !=','SYSTEM');$rows=$this->db->order_by('created_at')->get('messages')->result_array();$entries=array();foreach($rows as $r)$entries[]=array('id'=>$r['id'],'role'=>strtolower($r['role']),'author'=>$r['role']==='USER'?'User':'Assistant','content'=>$r['content'],'createdAt'=>$r['created_at'],'modelId'=>$r['model_id']);return array('conversationId'=>$cid,'title'=>$conv['title'],'generatedAt'=>date('c'),'messageCount'=>count($entries),'entries'=>$entries);}
 public function restore($cid,$uid,$org){$r=$this->db->where(array('id'=>$cid,'created_by_id'=>$uid,'organization_id'=>$org))->where('deleted_at IS NOT NULL',NULL,FALSE)->get('conversations')->row_array();if(!$r)return NULL;$now=date('Y-m-d H:i:s');$this->db->where('id',$cid)->update('conversations',array('deleted_at'=>NULL,'updated_at'=>$now));return array('id'=>$cid,'title'=>$r['title'],'restoredAt'=>$now);}
 public function message($cid,$mid,$uid,$org){if(!$this->access($cid,$uid,$org))return NULL;$r=$this->db->where(array('id'=>$mid,'conversation_id'=>$cid))->get('messages')->row_array();return $r?$this->message_view($r):NULL;}
 public function edit_message($cid,$mid,$uid,$org,$content){$r=$this->db->where(array('id'=>$mid,'conversation_id'=>$cid,'user_id'=>$uid,'role'=>'USER'))->get('messages')->row_array();if(!$r||!$this->access($cid,$uid,$org))return NULL;$meta=json_decode($r['metadata'],TRUE)?:array();$meta['conversationOps']['edits'][]=array('content'=>$r['content'],'editedAt'=>date('c'));$set=array('content'=>$content,'metadata'=>json_encode($meta),'updated_at'=>date('Y-m-d H:i:s'));$this->db->where('id',$mid)->update('messages',$set);return $this->message_view(array_merge($r,$set));}
 public function redact_message($cid,$mid,$uid,$org,$reason){$r=$this->db->where(array('id'=>$mid,'conversation_id'=>$cid))->get('messages')->row_array();if(!$r||!$this->access($cid,$uid,$org))return NULL;$conv=$this->db->where('id',$cid)->get('conversations')->row_array();if($r['user_id']!==$uid&&$conv['created_by_id']!==$uid)return NULL;$meta=json_decode($r['metadata'],TRUE)?:array();$meta['conversationOps']['redaction']=array('reason'=>$reason,'redactedAt'=>date('c'),'redactedBy'=>$uid);$set=array('content'=>'[redacted]','metadata'=>json_encode($meta),'updated_at'=>date('Y-m-d H:i:s'));$this->db->where('id',$mid)->update('messages',$set);return $this->message_view(array_merge($r,$set));}
 private function message_view($r){$meta=json_decode($r['metadata'],TRUE)?:array();return array('id'=>$r['id'],'conversationId'=>$r['conversation_id'],'role'=>strtolower($r['role']),'content'=>$r['content'],'status'=>strtolower($r['status']),'userId'=>$r['user_id'],'agentId'=>$r['agent_id'],'parentId'=>$r['parent_id'],'modelId'=>$r['model_id'],'tokensIn'=>$r['tokens_in'],'tokensOut'=>$r['tokens_out'],'costMicros'=>$r['cost_micros'],'durationMs'=>$r['duration_ms'],'citations'=>json_decode($r['citations'],TRUE)?:array(),'metadata'=>$meta,'createdAt'=>$r['created_at'],'updatedAt'=>$r['updated_at'],'edited'=>!empty($meta['conversationOps']['edits']),'redacted'=>!empty($meta['conversationOps']['redaction']));}
 public function search($uid,$org,$q,$cid,$role,$page,$per){$this->db->select('m.*,c.title conversation_title')->from('messages m')->join('conversations c','c.id=m.conversation_id')->where(array('c.organization_id'=>$org,'c.deleted_at'=>NULL))->group_start()->where('c.created_by_id',$uid)->or_where("EXISTS (SELECT 1 FROM conversation_participants cp WHERE cp.conversation_id=c.id AND cp.user_id=".$this->db->escape($uid).')',NULL,FALSE)->group_end()->like('m.content',$q);if($cid)$this->db->where('m.conversation_id',$cid);if($role)$this->db->where('m.role',strtoupper($role));$base=clone $this->db;$total=$base->count_all_results();$rows=$this->db->order_by('m.created_at','DESC')->limit($per,($page-1)*$per)->get()->result_array();$hits=array();foreach($rows as $r)$hits[]=array('message'=>$this->message_view($r),'conversation'=>array('id'=>$r['conversation_id'],'title'=>$r['conversation_title']),'matchType'=>'substring');return array('items'=>$hits,'query'=>$q,'matchType'=>'substring','pagination'=>array('page'=>$page,'perPage'=>$per,'total'=>$total,'totalPages'=>(int)ceil($total/$per)));}
 public function deleted($uid,$org,$page,$per){$this->db->from('conversations')->where(array('organization_id'=>$org,'created_by_id'=>$uid))->where('deleted_at IS NOT NULL',NULL,FALSE);$total=$this->db->count_all_results();$rows=$this->db->where(array('organization_id'=>$org,'created_by_id'=>$uid))->where('deleted_at IS NOT NULL',NULL,FALSE)->order_by('deleted_at','DESC')->limit($per,($page-1)*$per)->get('conversations')->result_array();$items=array_map(function($r){return array('id'=>$r['id'],'title'=>$r['title'],'deletedAt'=>$r['deleted_at'],'createdAt'=>$r['created_at'],'lastMessageAt'=>$r['last_message_at']);},$rows);return array('items'=>$items,'pagination'=>array('page'=>$page,'perPage'=>$per,'total'=>$total,'totalPages'=>(int)ceil($total/$per)));}
 public function unread($uid,$org,$limit){$rows=$this->db->select('c.id,c.title,c.last_message_at,p.last_read_at')->from('conversations c')->join('conversation_participants p','p.conversation_id=c.id AND p.user_id='.$this->db->escape($uid),'left')->where(array('c.organization_id'=>$org,'c.deleted_at'=>NULL))->group_start()->where('c.created_by_id',$uid)->or_where('p.user_id',$uid)->group_end()->order_by('c.last_message_at','DESC')->limit($limit)->get()->result_array();$items=array();$sum=0;foreach($rows as $r){$this->db->from('messages')->where('conversation_id',$r['id'])->group_start()->where('user_id IS NULL',NULL,FALSE)->or_where('user_id !=',$uid)->group_end();if($r['last_read_at'])$this->db->where('created_at >',$r['last_read_at']);$n=$this->db->count_all_results();if($n){$items[]=array('conversationId'=>$r['id'],'title'=>$r['title'],'unreadCount'=>$n,'lastMessageAt'=>$r['last_message_at'],'lastReadAt'=>$r['last_read_at'],'basis'=>$r['last_read_at']?'last_read_at':'never_marked_read');$sum+=$n;}}return array('items'=>$items,'totalUnread'=>$sum,'conversationsWithUnread'=>count($items),'inspectedConversations'=>count($rows),'truncated'=>count($rows)>=$limit,'generatedAt'=>date('c'));}
 public function digest($cid,$uid,$org,$max){$t=$this->transcript($cid,$uid,$org,FALSE);if(!$t)return NULL;$text='';foreach($t['entries'] as $e)$text.=' '.$e['content'];$words=preg_split('/[^\pL\pN]+/u',mb_strtolower($text),-1,PREG_SPLIT_NO_EMPTY);$stop=array_flip(array('the','and','that','this','with','from','have','for','you','your','are','was','were','but','not','can','will','into','about','they','them'));$freq=array();foreach($words as $w)if(mb_strlen($w)>=4&&!isset($stop[$w]))$freq[$w]=($freq[$w]??0)+1;arsort($freq);$terms=array();foreach(array_slice($freq,0,$max,TRUE) as $term=>$count)$terms[]=array('term'=>$term,'count'=>$count);$summary='';foreach($t['entries'] as $e){if($e['content']!=='[redacted]'){$summary=mb_substr(trim($e['content']),0,500);break;}}return array('conversationId'=>$cid,'summary'=>$summary,'keywords'=>$terms,'messageCount'=>$t['messageCount'],'method'=>'extractive_frequency','generatedAt'=>date('c'));}
 private function uuid(){$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));}
}
